import{d as a,S as o,i as n,l as t}from"./chunks/framework.CY2TYXqZ.js";const p=JSON.parse('{"title":"Staff Only","description":"A black-box engagement against Corkboard, an intranet noticeboard whose admin console is meant to open only for accounts carrying the administrator flag.","frontmatter":{"title":"Staff Only","number":2,"layout":"challenge","difficulty":"easy","category":"web","backend":"flask","app":"app.py","packages":["flask"],"tools":["browser","network","repeater","code"],"source_visible":false,"date":"2026-08-17T16:21:14.557Z","tags":["sql","injection","flask","sqlite"],"description":"A black-box engagement against Corkboard, an intranet noticeboard whose admin console is meant to open only for accounts carrying the administrator flag.","wasmModule":"/challenge/staff-only/runtime.wasm","markdownBody":"\\n# Staff Only\\n\\n**Client:** Corkboard, the intranet noticeboard a mid-sized company runs for its staff.\\n**Engagement:** Black-box assessment of the Corkboard web application.\\n\\n## Scope\\n\\nIn scope: the Corkboard application served at this origin and every HTTP\\nendpoint it exposes.\\n\\nCorkboard has issued you one staff account for this engagement — staff ID\\n`j.kerr`, password `Aut2026!`. It is an ordinary account with no elevated\\nrights, and it is the only credential you have been given.\\n\\nOut of scope: the hosting platform, other engagements, and denial of service.\\n\\n## Rules of engagement\\n\\nThis is an authorised exercise against a system Corkboard controls. Reach the\\nobjective and stop — Corkboard is paying for proof of impact, not for damage.\\nConfine any change you make to what the objective requires, and stay inside the\\nscope above.\\n\\nCorkboard has not released the application\'s source code for this engagement.\\nWork from what the running system tells you.\\n\\n## Constraints\\n\\nCorkboard is not buying a password audit. Guessing, spraying, or brute-forcing\\ncredentials is out of scope, and the engagement will not be accepted on that\\nbasis. The finding they want is one the application hands you.\\n\\n## Objective\\n\\nCorkboard tells its staff two things. Colleagues\' records are theirs alone —\\nthe profile editor opens your own entry and nobody else\'s. And the admin\\nconsole is restricted to accounts carrying the administrator flag, so the\\naccount you have been issued can never reach it.\\n\\nBoth statements are load-bearing, and Corkboard\'s own team has stopped\\nvouching for the first one.\\n\\nDisprove them: starting from the ordinary staff account above, reach the admin\\nconsole and recover the deployment recovery key it holds. That key is what\\nCorkboard will accept as proof of impact. Submit it below to close the\\nengagement.\\n\\n## Deliverable\\n\\nCorkboard wants a record of how you got there, not only the result. Log each\\nrequest that moved the assessment forward in the Notes panel, and export the\\nsession when you are done.\\n"},"headers":[],"relativePath":"challenge/staff-only/index.md","filePath":"challenge/staff-only/index.md"}'),r={name:"challenge/staff-only/index.md"};function s(i,e,d,c,l,h){return o(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="staff-only" tabindex="-1">Staff Only <a class="header-anchor" href="#staff-only" aria-label="Permalink to “Staff Only”">​</a></h1><p><strong>Client:</strong> Corkboard, the intranet noticeboard a mid-sized company runs for its staff. <strong>Engagement:</strong> Black-box assessment of the Corkboard web application.</p><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to “Scope”">​</a></h2><p>In scope: the Corkboard application served at this origin and every HTTP endpoint it exposes.</p><p>Corkboard has issued you one staff account for this engagement — staff ID <code>j.kerr</code>, password <code>Aut2026!</code>. It is an ordinary account with no elevated rights, and it is the only credential you have been given.</p><p>Out of scope: the hosting platform, other engagements, and denial of service.</p><h2 id="rules-of-engagement" tabindex="-1">Rules of engagement <a class="header-anchor" href="#rules-of-engagement" aria-label="Permalink to “Rules of engagement”">​</a></h2><p>This is an authorised exercise against a system Corkboard controls. Reach the objective and stop — Corkboard is paying for proof of impact, not for damage. Confine any change you make to what the objective requires, and stay inside the scope above.</p><p>Corkboard has not released the application&#39;s source code for this engagement. Work from what the running system tells you.</p><h2 id="constraints" tabindex="-1">Constraints <a class="header-anchor" href="#constraints" aria-label="Permalink to “Constraints”">​</a></h2><p>Corkboard is not buying a password audit. Guessing, spraying, or brute-forcing credentials is out of scope, and the engagement will not be accepted on that basis. The finding they want is one the application hands you.</p><h2 id="objective" tabindex="-1">Objective <a class="header-anchor" href="#objective" aria-label="Permalink to “Objective”">​</a></h2><p>Corkboard tells its staff two things. Colleagues&#39; records are theirs alone — the profile editor opens your own entry and nobody else&#39;s. And the admin console is restricted to accounts carrying the administrator flag, so the account you have been issued can never reach it.</p><p>Both statements are load-bearing, and Corkboard&#39;s own team has stopped vouching for the first one.</p><p>Disprove them: starting from the ordinary staff account above, reach the admin console and recover the deployment recovery key it holds. That key is what Corkboard will accept as proof of impact. Submit it below to close the engagement.</p><h2 id="deliverable" tabindex="-1">Deliverable <a class="header-anchor" href="#deliverable" aria-label="Permalink to “Deliverable”">​</a></h2><p>Corkboard wants a record of how you got there, not only the result. Log each request that moved the assessment forward in the Notes panel, and export the session when you are done.</p>',17)])])}const g=a(r,[["render",s]]);export{p as __pageData,g as default};
